CREATE TABLE IF NOT EXISTS job_reviews (owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, id TEXT NOT NULL, resume_id TEXT NOT NULL, request_hash TEXT NOT NULL, saved_at TEXT NOT NULL, report TEXT NOT NULL CHECK(json_valid(report) AND json_extract(report,'$.id')=id AND json_extract(report,'$.sourceId')=resume_id AND json_extract(report,'$.schemaVersion')=1), PRIMARY KEY(owner_id,id), FOREIGN KEY(owner_id,resume_id) REFERENCES resumes(owner_id,id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS job_reviews_resume_saved ON job_reviews(owner_id,resume_id,saved_at DESC);
